<script setup>
import { ref, onMounted, onUnmounted } from 'vue'
import { Pause, Play, ArrowLeft, RotateCcw, Headphones } from '@lucide/vue'
import { GameEngine, saveResult } from '../lib/game-engine.js'
const props=defineProps({mode:String,sound:Boolean,motion:Boolean}), emit=defineEmits(['exit','finish'])
const canvas=ref(null), phase=ref('loading'), error=ref(''), score=ref(0), combo=ref(0), remaining=ref('3:42'), countdown=ref(3), feedback=ref(''), active=ref([false,false,false,false])
let audio,engine,chart,ctx,raf,observer,w=400,h=600,time=-3,startAt=0,resumeAt=0,lastUI=0,disposed=false,finishing=false,feedbackUntil=0,beginToken=0
const fingers=new Map(), keys=new Set(), sparks=[]
const controller=new AbortController()
function resize(){if(!canvas.value)return;const r=canvas.value.getBoundingClientRect();w=r.width;h=r.height;const d=Math.min(devicePixelRatio,2);canvas.value.width=w*d;canvas.value.height=h*d;ctx.setTransform(d,0,0,d,0,0);draw()}
function rounded(x,y,width,height,r=9){ctx.beginPath();ctx.roundRect(x,y,width,height,r)}
function draw(){if(!ctx||!engine)return;ctx.clearRect(0,0,w,h);const lane=w/4,line=h*.81,travel=line/chart.approachTimeSeconds
 for(let i=0;i<4;i++){const g=ctx.createLinearGradient(0,0,0,h);g.addColorStop(0,'rgba(61,116,171,.01)');g.addColorStop(1,active.value[i]?'rgba(135,198,255,.22)':'rgba(36,77,125,.13)');ctx.fillStyle=g;ctx.fillRect(i*lane,0,lane,h);ctx.strokeStyle='rgba(185,215,255,.14)';ctx.beginPath();ctx.moveTo(i*lane+.5,0);ctx.lineTo(i*lane+.5,h);ctx.stroke()}
 for(const n of engine.notes){if(n.state==='hit'||n.state==='miss')continue;let y=line-(n.timeSeconds-time)*travel;const length=n.type==='hold'?(n.state==='holding'?Math.max(8,(n.timeSeconds+n.durationSeconds-time)*travel):Math.max(70,n.durationSeconds*travel)):Math.min(105,h*.17);if(y<-length||y>h+length)continue;if(n.state==='holding')y=line;const x=n.lane*lane+lane*.12,top=y-length;const g=ctx.createLinearGradient(x,top,x+lane*.76,y);g.addColorStop(0,n.lane%2?'#d6ecff':'#f8f7ec');g.addColorStop(.5,n.lane%2?'#8fc4f4':'#d6e5f1');g.addColorStop(1,n.lane%2?'#528cde':'#97b8d6');ctx.fillStyle=g;ctx.shadowColor='#80c6ff';ctx.shadowBlur=props.motion?12:0;rounded(x,top,lane*.76,length);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='rgba(255,255,255,.8)';ctx.lineWidth=1;ctx.stroke();ctx.fillStyle='rgba(255,255,255,.35)';rounded(x+4,top+4,lane*.76-8,3,1);ctx.fill();if(n.type==='hold'){ctx.strokeStyle='rgba(255,255,255,.55)';ctx.beginPath();ctx.moveTo(x+lane*.38,top+15);ctx.lineTo(x+lane*.38,y-12);ctx.stroke()}}
 const glow=ctx.createLinearGradient(0,line-14,0,line+14);glow.addColorStop(0,'rgba(255,222,162,0)');glow.addColorStop(.5,'rgba(255,227,175,.4)');glow.addColorStop(1,'rgba(255,222,162,0)');ctx.fillStyle=glow;ctx.fillRect(0,line-14,w,28);ctx.shadowColor='#ffe4af';ctx.shadowBlur=20;ctx.fillStyle='#fff1d4';ctx.fillRect(0,line-1,w,2);ctx.shadowBlur=0
 if(props.motion){const now=performance.now();for(let i=sparks.length-1;i>=0;i--){const p=sparks[i],age=(now-p.born)/600;if(age>1){sparks.splice(i,1);continue}ctx.globalAlpha=1-age;ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x+p.vx*age,line+p.vy*age+60*age*age,p.size*(1-age*.7),0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}
}
function updateUI(){score.value=engine.score;combo.value=engine.combo;const s=Math.round(Math.max(0,chart.durationSeconds-Math.max(0,time)));remaining.value=`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`}
function frame(now){if(disposed)return;if(phase.value==='countdown'){time=resumeAt-(startAt-now)/1000;countdown.value=Math.max(1,Math.ceil((startAt-now)/1000));if(now>=startAt){audio.currentTime=resumeAt;phase.value='starting';audio.play().then(()=>{if(disposed||phase.value!=='starting'){audio.pause();return}phase.value='playing'}).catch(()=>{error.value='La lecture a été interrompue. Touchez Reprendre pour réessayer.';phase.value='paused'})}}
 if(phase.value==='playing'){time=audio.currentTime;const events=engine.advance(time);if(events.some(e=>e.type==='miss')){feedback.value='Retrouvez le rythme';feedbackUntil=now+450}if(audio.ended||time>=chart.durationSeconds-.03)finish()}
 if(engine){draw();if(now-lastUI>65){updateUI();lastUI=now}if(now>feedbackUntil)feedback.value=''}raf=requestAnimationFrame(frame)}
async function begin(){if(!['ready','paused'].includes(phase.value)||disposed)return;const token=++beginToken;error.value='';phase.value='priming';try{audio.currentTime=resumeAt;audio.muted=true;await audio.play();if(disposed||token!==beginToken){audio.pause();return}audio.pause();audio.muted=!props.sound;audio.currentTime=resumeAt;startAt=performance.now()+3000;time=resumeAt-3;phase.value='countdown';countdown.value=3}catch{if(disposed||token!==beginToken)return;audio.muted=!props.sound;error.value='La musique ne peut pas démarrer. Vérifiez votre connexion puis réessayez.';phase.value='paused'}}
function pause(){if(!['playing','countdown','starting','priming'].includes(phase.value))return;beginToken++;audio.pause();if(phase.value==='playing')resumeAt=engine.rewindTo(Math.max(0,audio.currentTime-2));time=resumeAt;active.value=[false,false,false,false];fingers.clear();keys.clear();phase.value='paused';updateUI()}
function feedbackHit(event){if(!event||event.type==='ignored')return;feedback.value=event.type==='perfect'?'Parfait':event.type==='good'?'Bien joué':event.type==='early-release'?'Maintenez jusqu’au bout':'Sur la ligne !';feedbackUntil=performance.now()+450;if(['perfect','good'].includes(event.type)&&props.motion){for(let i=0;i<18;i++)sparks.push({x:(event.lane+.5)*w/4,vx:(Math.random()-.5)*140,vy:-Math.random()*95-15,size:Math.random()*2+1,born:performance.now(),color:i%3?'#f8dfac':'#b5dfff'})}}
function press(lane){if(phase.value!=='playing'||active.value[lane])return;active.value[lane]=true;feedbackHit(engine.hit(lane,audio.currentTime));updateUI()}
function release(lane){if(phase.value==='playing'){feedbackHit(engine.release(lane,audio.currentTime));updateUI()}active.value[lane]=false}
function down(e,lane){if(phase.value!=='playing')return;e.preventDefault();e.currentTarget.setPointerCapture(e.pointerId);fingers.set(e.pointerId,lane);press(lane)}
function up(e){const lane=fingers.get(e.pointerId);if(lane===undefined)return;fingers.delete(e.pointerId);if(![...fingers.values()].includes(lane))release(lane)}
function keydown(e){const lane=['KeyD','KeyF','KeyJ','KeyK'].indexOf(e.code);if(lane>=0){e.preventDefault();if(e.repeat||keys.has(e.code))return;keys.add(e.code);press(lane)}if(e.code==='Space'||e.code==='Escape'){e.preventDefault();if(e.repeat)return;if(phase.value==='playing'||phase.value==='countdown')pause();else if(phase.value==='paused')begin()}}
function keyup(e){const lane=['KeyD','KeyF','KeyJ','KeyK'].indexOf(e.code);keys.delete(e.code);if(lane>=0)release(lane)}
function hidden(){if(document.hidden)pause()}
function finish(){if(finishing||disposed||phase.value!=='playing')return;finishing=true;audio.pause();engine.advance(chart.durationSeconds+1);const result=engine.result();result.saved=saveResult(result);emit('finish',result)}
function retry(){engine.reset();resumeAt=0;time=-3;score.value=combo.value=0;feedback.value='';sparks.length=0;begin()}
onMounted(async()=>{ctx=canvas.value.getContext('2d');observer=new ResizeObserver(resize);observer.observe(canvas.value);window.addEventListener('keydown',keydown);window.addEventListener('keyup',keyup);window.addEventListener('blur',pause);document.addEventListener('visibilitychange',hidden)
 try{const response=await fetch(`/music/${props.mode}.json`,{signal:controller.signal});if(!response.ok)throw Error('chart');chart=await response.json();if(disposed)return;engine=new GameEngine(chart);audio=new Audio('/music/emilie.mp3');audio.preload='auto';audio.volume=.8;audio.muted=!props.sound;audio.addEventListener('ended',finish);audio.addEventListener('error',()=>{if(disposed)return;pause();error.value='Le morceau est indisponible. Revenez au choix du niveau et réessayez.'});audio.load();phase.value='ready';resize();raf=requestAnimationFrame(frame)}catch(e){if(!disposed){phase.value='error';error.value='Le morceau n’a pas pu être chargé. Vérifiez votre connexion.'}}})
onUnmounted(()=>{disposed=true;beginToken++;controller.abort();cancelAnimationFrame(raf);observer?.disconnect();audio?.pause();if(audio){audio.removeEventListener('ended',finish);audio.removeAttribute('src');audio.load()}window.removeEventListener('keydown',keydown);window.removeEventListener('keyup',keyup);window.removeEventListener('blur',pause);document.removeEventListener('visibilitychange',hidden)})
</script>
<template>
<section class="game-screen">
 <header class="game-hud"><button class="icon-button" aria-label="Mettre en pause" @click="pause"><Pause :size="24"/></button><div><span>SCORE</span><strong>{{score.toLocaleString('fr-FR')}}</strong><b :class="{lit:combo>4}">{{combo>1?'COMBO ×'+combo:'À VOUS DE BRILLER'}}</b></div><span class="game-time">✧ {{remaining}}</span></header>
 <div class="track-wrap"><canvas ref="canvas" class="game-canvas" aria-label="Quatre pistes de notes. Jouez avec D, F, J, K ou les touches en bas."/><div class="hit-feedback" :class="{visible:feedback}">{{feedback}}</div><div class="piano-controls"><button v-for="(key,i) in ['D','F','J','K']" :key="key" :class="{pressed:active[i]}" :aria-label="'Touche '+(i+1)+' — '+key" @pointerdown="down($event,i)" @pointerup="up" @pointercancel="up" @lostpointercapture="up"><span>{{key}}</span><i></i></button></div></div>
 <footer class="game-song"><span class="song-mini">✦</span><div><strong>Dans les yeux d’Émilie</strong><span>Joe Dassin · {{mode}}</span></div><div class="equalizer" :class="{running:phase==='playing'&&motion}"><i v-for="i in 5" :key="i" :style="{'--i':i}"></i></div></footer>
 <div v-if="['loading','priming','ready','paused','error'].includes(phase)" class="game-overlay"><div class="game-dialog"><Headphones :size="32"/><p class="eyebrow">{{phase==='paused'?'UN INSTANT SUSPENDU':'LA SCÈNE EST À VOUS'}}</p><h1>{{['loading','priming'].includes(phase)?'La magie arrive…':phase==='paused'?'Reprenez le rythme.':'Prêt à briller ?'}}</h1><p v-if="phase!=='paused'">Appuyez sur les touches du bas quand une note atteint la ligne dorée.<br>Maintenez les notes longues jusqu’au bout.</p><p v-else>La musique reprend deux secondes plus tôt pour retrouver vos repères.</p><div class="key-guide" v-if="phase==='ready'"><kbd>D</kbd><kbd>F</kbd><kbd>J</kbd><kbd>K</kbd></div><p class="error-message" v-if="error" role="alert">{{error}}</p><button v-if="phase==='ready'||phase==='paused'" class="primary-button" @click="begin"><Play :size="18"/>{{phase==='paused'?'Reprendre':'Lancer la musique'}}</button><button v-if="phase==='paused'" class="text-button" @click="retry"><RotateCcw :size="15"/> Recommencer</button><button class="text-button" @click="emit('exit')"><ArrowLeft :size="15"/> Choisir mon niveau</button></div></div>
 <div v-if="phase==='countdown'" class="countdown-overlay" aria-live="assertive"><strong :key="countdown">{{countdown}}</strong><span>Suivez la lumière</span></div>
</section>
</template>
<style scoped>
.game-screen{position:relative;max-width:580px;margin:auto;height:100svh;min-height:540px;display:flex;flex-direction:column;background:linear-gradient(180deg,rgba(1,13,28,.75),rgba(4,21,42,.45));box-shadow:0 0 100px #0008;overflow:hidden}.game-hud{padding:26px 22px 10px;padding-top:max(26px,env(safe-area-inset-top));display:flex;justify-content:space-between;align-items:flex-start;z-index:2}.game-hud>div{text-align:center;display:flex;flex-direction:column}.game-hud span{font-size:11px;letter-spacing:2px;color:#c4d4e8}.game-hud strong{font-size:46px;line-height:1.15;font-weight:700;color:#fff5e1;font-variant-numeric:tabular-nums}.game-hud b{font-size:11px;color:#d6bc85;margin-top:7px;letter-spacing:1px}.game-hud b.lit{text-shadow:0 0 14px #ffc864}.game-time{padding-top:13px!important;letter-spacing:0!important;min-width:62px;text-align:right}.track-wrap{flex:1;position:relative;min-height:0;margin:0 22px}.game-canvas{width:100%;height:100%;display:block}.piano-controls{position:absolute;bottom:2%;height:14%;left:0;right:0;display:grid;grid-template-columns:repeat(4,1fr);gap:12px;padding:0 6px;touch-action:none}.piano-controls button{position:relative;touch-action:none;user-select:none;border:1px solid #b3d3f8;border-radius:8px;background:linear-gradient(135deg,#cedff15c,#38659955);box-shadow:inset 0 0 13px #e6f2ff44,0 4px 0 #122e50;transform:perspective(250px) rotateX(14deg);color:#e3edf8;font-size:13px;transition:background .08s,box-shadow .08s}.piano-controls button.pressed{background:#a9d8ffaa;box-shadow:0 0 35px #b8e1ff99,inset 0 0 18px white;transform:perspective(250px) rotateX(14deg) translateY(3px)}.piano-controls span{opacity:.5}.piano-controls i{position:absolute;bottom:8px;left:30%;width:40%;height:2px;background:#c5e2ff88}.hit-feedback{position:absolute;top:48%;left:0;right:0;text-align:center;font-family:'Cormorant Garamond',serif;font-size:29px;color:#ffe1a2;text-shadow:0 0 22px #ecc17a;opacity:0;transform:translateY(8px);transition:opacity .12s,transform .18s;pointer-events:none}.hit-feedback.visible{opacity:1;transform:none}.game-song{display:flex;align-items:center;gap:13px;padding:15px 28px max(22px,env(safe-area-inset-bottom));background:#03101ccc}.song-mini{width:43px;height:43px;border-radius:8px;background:linear-gradient(40deg,#143966,#487690);display:grid;place-items:center;color:#f9d79c;font-size:26px;border:1px solid #93b3d2}.game-song>div:nth-child(2){display:flex;flex-direction:column;gap:4px}.game-song strong{font-size:12px}.game-song span:not(.song-mini){font-size:11px;color:#9db2c9}.equalizer{margin-left:auto;display:flex;align-items:center;gap:3px;height:30px}.equalizer i{width:2px;height:calc(8px + var(--i)*3px);background:#d6e7ff;box-shadow:0 0 6px #6eabff}.equalizer.running i{animation:eq .8s ease-in-out infinite alternate;animation-delay:calc(var(--i)*-.17s)}@keyframes eq{to{transform:scaleY(.3)}}.game-overlay{position:absolute;inset:0;display:grid;place-items:center;background:#020d1cd9;backdrop-filter:blur(14px);z-index:5;padding:25px}.game-dialog{text-align:center;max-width:360px;width:100%}.game-dialog>svg{color:#dbbf88;margin-bottom:22px}.game-dialog h1{font-family:'Cormorant Garamond',serif;font-size:45px;line-height:1;margin:18px 0}.game-dialog>p:not(.eyebrow){font-size:13px;line-height:1.8;color:#b9cce0;margin:18px 0 25px}.game-dialog .text-button{display:flex;align-items:center;justify-content:center;gap:8px}.key-guide{display:flex;justify-content:center;gap:12px;margin:20px 0 30px}.key-guide kbd{padding:10px 15px;border:1px solid #8aa9c759;background:#a3c5e911;border-radius:6px}.countdown-overlay{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;pointer-events:none;background:#03111b44}.countdown-overlay strong{font:120px 'Cormorant Garamond',serif;color:#fff0d4;text-shadow:0 0 45px #dbb875;animation:count .9s ease-out both}.countdown-overlay span{color:#c9d9e9;font-size:12px;letter-spacing:3px;text-transform:uppercase}@keyframes count{from{opacity:0;transform:scale(1.2)}30%{opacity:1}to{opacity:.7;transform:scale(.95)}}@media(max-width:600px){.game-hud{padding:20px 18px 8px}.game-hud strong{font-size:42px}.piano-controls{gap:9px}.track-wrap{margin:0 14px}.piano-controls span{opacity:.3}.game-song{padding-left:20px;padding-right:20px}}
</style>
